widget.solution:
def count_overlapping_pairs(intervals):
    events = []
    for s, e in intervals:
        events.append((s, 1))
        events.append((e, -1))
    events.sort()   # at equal times -1 sorts first: touching ends do not overlap
    active = pairs = 0
    for _, step in events:
        if step == 1:
            pairs += active
        active += step
    return pairs
